CREATE TABLE screening_row_link_versions(
 id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),project_id TEXT NOT NULL REFERENCES screening_project_versions(id),batch_id TEXT NOT NULL REFERENCES screening_batch_versions(id),batch_version_id TEXT NOT NULL REFERENCES screening_batch_versions(id),row_number INTEGER NOT NULL CHECK(row_number BETWEEN 1 AND 500),row_snapshot_json TEXT NOT NULL CHECK(json_valid(row_snapshot_json)),revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),action TEXT NOT NULL CHECK(action IN('link','withdraw')),customer_id TEXT NOT NULL,customer_version INTEGER NOT NULL,project_version_id TEXT NOT NULL REFERENCES screening_project_versions(id),project_sequence INTEGER NOT NULL CHECK(project_sequence>0),batch_sequence INTEGER NOT NULL CHECK(batch_sequence>0),customer_profile_prefix INTEGER NOT NULL CHECK(customer_profile_prefix>0),record_reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),actor_role TEXT NOT NULL CHECK(actor_role IN('manager','reception','professional')),
 FOREIGN KEY(customer_id,customer_version) REFERENCES customer_profile_versions(customer_id,version),UNIQUE(batch_version_id,row_number,revision),UNIQUE(store_id,sequence)
);
CREATE VIEW screening_row_link_current AS SELECT v.* FROM screening_row_link_versions v WHERE revision=(SELECT max(revision) FROM screening_row_link_versions WHERE batch_version_id=v.batch_version_id AND row_number=v.row_number);
CREATE TRIGGER screening_row_link_source BEFORE INSERT ON screening_row_link_versions BEGIN
 SELECT CASE WHEN NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM screening_row_link_versions WHERE store_id=NEW.store_id),1) OR NEW.revision<>coalesce((SELECT revision+1 FROM screening_row_link_current WHERE batch_version_id=NEW.batch_version_id AND row_number=NEW.row_number),1) THEN RAISE(ABORT,'screening row link continuous history') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM screening_batch_versions b JOIN customers c ON c.id=NEW.customer_id WHERE b.id=NEW.batch_version_id AND b.root_id=NEW.batch_id AND b.project_id=NEW.project_id AND b.store_id=NEW.store_id AND c.store_id=NEW.store_id AND NEW.row_snapshot_json=screening_csv_row(b.csv_text,NEW.row_number,b.created_at)) THEN RAISE(ABORT,'screening row link exact original row and customer store') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM screening_project_current p JOIN users u ON u.id=NEW.created_by LEFT JOIN user_security s ON s.user_id=u.id WHERE p.root_id=NEW.project_id AND p.id=NEW.project_version_id AND p.store_id=NEW.store_id AND u.role=NEW.actor_role AND u.store_id=NEW.store_id AND u.active=1 AND coalesce(s.must_change_password,0)=0 AND (u.role='manager' OR u.id=p.owner_id)) THEN RAISE(ABORT,'screening row link current responsibility') END;
 SELECT CASE WHEN NEW.project_sequence IS NOT (SELECT max(sequence) FROM screening_project_versions WHERE store_id=NEW.store_id) OR NEW.batch_sequence IS NOT (SELECT max(sequence) FROM screening_batch_versions WHERE store_id=NEW.store_id) OR NEW.customer_profile_prefix IS NOT (SELECT max(rowid) FROM customer_profile_versions) THEN RAISE(ABORT,'screening row link original history prefixes') END;
 SELECT CASE WHEN NEW.action='link' AND (EXISTS(SELECT 1 FROM screening_row_link_current WHERE batch_version_id=NEW.batch_version_id AND row_number=NEW.row_number AND action='link') OR json_array_length(NEW.row_snapshot_json,'$.errors')<>0 OR NOT EXISTS(SELECT 1 FROM screening_batch_current WHERE id=NEW.batch_version_id) OR NOT EXISTS(SELECT 1 FROM screening_project_current p JOIN users owner ON owner.id=p.owner_id LEFT JOIN user_security s ON s.user_id=owner.id WHERE p.id=NEW.project_version_id AND p.action='record' AND p.authorization_status='recorded' AND owner.store_id=p.store_id AND owner.active=1 AND owner.role IN('manager','reception','professional') AND coalesce(s.must_change_password,0)=0) OR NEW.customer_version IS NOT (SELECT max(version) FROM customer_profile_versions WHERE customer_id=NEW.customer_id) OR NOT EXISTS(SELECT 1 FROM customers c JOIN customer_profile_versions p ON p.customer_id=c.id AND p.version=NEW.customer_version WHERE c.id=NEW.customer_id AND c.name IS p.name AND c.birth_date IS p.birth_date AND c.contact_name IS p.contact_name AND c.phone IS p.phone)) THEN RAISE(ABORT,'screening row link explicit valid current adoption') END;
 SELECT CASE WHEN NEW.action='withdraw' AND NOT EXISTS(SELECT 1 FROM screening_row_link_current p WHERE p.batch_version_id=NEW.batch_version_id AND p.row_number=NEW.row_number AND p.action='link' AND p.customer_id=NEW.customer_id AND p.customer_version=NEW.customer_version AND p.row_snapshot_json=NEW.row_snapshot_json) THEN RAISE(ABORT,'screening row link withdrawal preserves original') END;
END;
CREATE TRIGGER screening_row_link_text_time BEFORE INSERT ON screening_row_link_versions WHEN length(trim(NEW.record_reason)) NOT BETWEEN 1 AND 300 OR length(NEW.record_reason)>300 OR instr(NEW.record_reason,char(0))>0 OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM screening_row_link_versions WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM screening_batch_versions WHERE id=NEW.batch_version_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM screening_project_versions WHERE id=NEW.project_version_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM customer_profile_versions WHERE customer_id=NEW.customer_id AND version=NEW.customer_version AND created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'screening row link explicit reason and source time');END;
CREATE TRIGGER screening_row_link_no_update BEFORE UPDATE ON screening_row_link_versions BEGIN SELECT RAISE(ABORT,'screening row link immutable history');END;
CREATE TRIGGER screening_row_link_no_delete BEFORE DELETE ON screening_row_link_versions BEGIN SELECT RAISE(ABORT,'screening row link immutable history');END;
